		27,
		-1,
		"",
		"字:28",
		"我接受了先生的安排接管第七孤儿院。\r\n其实我犹豫过是否应该放弃悠闲的退役生活接下这份不讨喜的差事，\r\n但先生告诉我七号孤儿院里的孤儿不是普通的孩子，他们是超凡者的后代。"
