		"",
		27,
		-1,
		"",
		"字:28",
		"8月，15日。\r\n沙利亚训练时觉醒去世。\r\n孩子们认知尚浅，无法理解“心锚”的概念，更无法在觉醒时构建出自己的“心锚”。\r\n在未来课程中，所有导师必须加强灌输“心锚”的概念及重要性，我不愿再看到牺牲。"
