		"",
		27,
		-1,
		"",
		"字:28",
		"11月29日。\r\n当我赶回孤儿院时西弗罗莎觉醒了，抑制剂在觉醒中途无法起到任何作用。\r\n我已经忘了这是第几次看到孩子们在我面前失控变成怪物，而我能做的事情竟是闭上眼睛，开枪。\r\n生命如此荒诞，昨天还在笑闹，在我面前为了一颗糖果撒娇，今天已然变成一具尸体。\r\n。"
